class Movie:
    def __init__(self, movie_name, total_seats, ticket_price):
        self.movie_name = movie_name
        self.total_seats = total_seats
        self.ticket_price = ticket_price
        self.booked_seats = 0

    def seats_available(self):
        return self.total_seats - self.booked_seats

    def book_ticket(self, num_tickets):
        if num_tickets <= self.seats_available():
            self.booked_seats += num_tickets
            print(f"Booked {num_tickets} ticket(s). Total to pay: {num_tickets * self.ticket_price}")
        else:
            print("Sorry, not enough seats available")

    def show_status(self):
        print(f"Movie: {self.movie_name}")
        print(f"Seats available: {self.seats_available()}")
        print(f"Seats booked: {self.booked_seats}")
